// Heating planning workflow structured by the SIA 108:2014 phases. Checklist items paraphrase the requirements of
// SIA 384/1:2022 (heating systems), SIA 384/2:2020 (design heat load), SIA 384/6:2021 (borehole heat exchangers),
// SIA 384/7:2015 (groundwater heat use),
// the EnDK aid EN-103 (2020), SWKI HE301-01 (safety equipment), the HAKA floor heating planning guide and the SIA 108
// basic services; `ref` names the clause to look up. Warmwasser belongs to the Sanitär planning.

import type { L10n, PlanChecklistItem } from "@/lib/planning";

import type { GeneratorType, HeatingParams } from "./plan-schema";

export type HeatingItem = PlanChecklistItem<HeatingParams>;

/** `fire`: Brandschutz section (VKF), mirrored in the Brandschutz dossier. */
export type HeatingSection = { kind: "checklist"; key: string; title: L10n; items: HeatingItem[]; fire?: true };

export type HeatingPhase = { code: string; sia108: string; title: L10n; goal: L10n; sections: HeatingSection[] };

type When = (p: HeatingParams) => boolean;

const i = (id: string, ref: string, de: string, fr: string, it: string, when?: When): HeatingItem => ({ id, ref, text: { de, fr, it }, when });
const list = (key: string, title: L10n, items: HeatingItem[]): HeatingSection => ({ kind: "checklist", key, title, items });
const fireList = (key: string, title: L10n, items: HeatingItem[]): HeatingSection => ({ kind: "checklist", key, title, items, fire: true });
const t = (de: string, fr: string, it: string): L10n => ({ de, fr, it });

const has =
  (...types: GeneratorType[]): When =>
  (p) =>
    types.some((g) => p.generators.includes(g));
const hp = has("hpAir", "hpBrine", "hpWater");
const bhe = has("hpBrine");
const gw = has("hpWater");
const combustion = has("pellets", "logWood", "gasOil");
const floor: When = (p) => p.emitters.includes("floor");
const existing: When = (p) => p.construction !== "new";
/** Threshold rules apply while the output or area is not known yet. */
const powerAbove = (kW: number): When => (p) => p.power === null || p.power > kW;
// Brandschutz (VKF BSR 24-15, 26-15)
const all = (...conds: When[]): When => (p) => conds.every((c) => c(p));
const any = (...conds: When[]): When => (p) => conds.some((c) => c(p));
const pellets = has("pellets");
const wood = has("pellets", "logWood");
const gasOil = has("gasOil");
const oil: When = (p) => gasOil(p) && p.fuel === "oil";
const gas: When = (p) => gasOil(p) && p.fuel === "gas";
const oilTank: When = (p) => p.oilTank;
const fireplace: When = (p) => p.fireplace;
const district = has("district");
const multi: When = (p) => p.buildingType !== "efh" || p.multiUnit;
const nonRes: When = (p) => p.buildingType === "nonResidential";

